D[77195]={"^Learn Random Cast Spell%s*$","Aprenda Feitiço de Lançamento Aleatório."}
D[77196]={"^Learn Random Main Spell %- Melee%s*$","Aprenda Feitiço Principal Aleatório - Corpo a corpo."}
